<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {ChartColumn} from '@lucide/vue'
import {chartAxisMaximum,incomeExpenseTrend,type TrendGranularity} from './ledgerStatistics'
import {money} from './ledgerViewModels'
import type {Transaction} from './ledger'
const props=defineProps<{transactions:Transaction[];start:Date;end:Date;period:'week'|'month'|'year'}>()
const granularity=ref<TrendGranularity>(props.period==='year'?'month':props.period==='month'?'week':'day'),selected=ref<string|null>(null)
watch(()=>props.period,value=>{granularity.value=value==='year'?'month':value==='month'?'week':'day';selected.value=null})
watch(granularity,()=>selected.value=null)
const points=computed(()=>incomeExpenseTrend(props.transactions,props.start,props.end,granularity.value))
const maximum=computed(()=>chartAxisMaximum(Math.max(0,...points.value.flatMap(point=>[point.expense,point.income]))))
const ticks=computed(()=>Array.from({length:5},(_,i)=>({value:maximum.value*(4-i)/4,y:12+i*43})))
const width=computed(()=>Math.max(260,points.value.length*42)),slot=computed(()=>width.value/points.value.length)
const active=computed(()=>points.value.find(point=>point.key===selected.value))
const totals=computed(()=>points.value.reduce((sum,point)=>({expense:sum.expense+point.expense,income:sum.income+point.income}),{expense:0,income:0}))
function axis(value:number){return value>=10000?`${Number((value/10000).toFixed(1))}万`:value>=1000?`${Number((value/1000).toFixed(1))}k`:Number(value.toFixed(2)).toString()}
</script>
<template>
  <article class="home-panel finance-trend" aria-label="收支趋势图"><header class="ft-heading"><div><h3>收支趋势</h3><p>本人收支，按{{ granularity==='day'?'日':granularity==='week'?'周':'月' }}查看</p></div><div class="ft-granularity" role="group" aria-label="趋势统计粒度"><button v-for="option in [{id:'day',label:'日'},{id:'week',label:'周'},{id:'month',label:'月'}] as const" :key="option.id" type="button" :aria-pressed="granularity===option.id" @click="granularity=option.id">{{ option.label }}</button></div></header>
    <div class="ft-legend"><span><i></i>支出</span><span><i></i>收入</span><small>点击柱形查看数值</small></div>
    <template v-if="transactions.length"><div class="ft-chart"><svg class="ft-axis" viewBox="0 0 42 211" aria-hidden="true"><text v-for="tick in ticks" :key="tick.y" x="36" :y="tick.y+4" text-anchor="end">{{ axis(tick.value) }}</text></svg><div class="ft-scroll" tabindex="0" aria-label="收支趋势，内容较多时可横向滑动"><svg :viewBox="`0 0 ${width} 211`" :style="{minWidth:`${points.length*37}px`}" role="group" aria-label="各期间的收入和支出"><line v-for="tick in ticks" :key="tick.y" x1="0" :x2="width" :y1="tick.y" :y2="tick.y" class="ft-grid"/><g v-for="(point,index) in points" :key="point.key" :transform="`translate(${slot*index},0)`" role="button" tabindex="0" :aria-label="`${point.label}，支出${money(point.expense)}，收入${money(point.income)}`" :aria-pressed="selected===point.key" @click="selected=point.key" @keydown.enter.prevent="selected=point.key" @keydown.space.prevent="selected=point.key"><rect x="1" y="0" :width="slot-2" height="189" rx="7" class="ft-hit" :class="{selected:selected===point.key}"/><rect :x="slot/2-10" :y="184-point.expense/maximum*172" width="8" :height="point.expense?Math.max(1,point.expense/maximum*172):0" rx="3" class="ft-expense"/><rect :x="slot/2+2" :y="184-point.income/maximum*172" width="8" :height="point.income?Math.max(1,point.income/maximum*172):0" rx="3" class="ft-income"/><text :x="slot/2" y="205" text-anchor="middle">{{ point.label }}</text><title>{{ point.label }}：支出 {{ money(point.expense) }}，收入 {{ money(point.income) }}</title></g></svg></div></div><div class="ft-values" aria-live="polite"><span>{{ active?.label||'本区间合计' }}</span><b class="ft-expense-text">支出 {{ money(active?.expense??totals.expense) }}</b><b class="ft-income-text">收入 {{ money(active?.income??totals.income) }}</b></div></template>
    <div v-else class="ft-empty"><ChartColumn :size="32"/><b>从第一笔开始积累</b><p>记录收支后，会在这里呈现变化趋势</p></div>
  </article>
</template>
<style scoped>
.finance-trend{min-width:0;align-self:start}.ft-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.ft-heading h3{margin:0 0 7px;font-size:15px}.ft-heading p{margin:0;font-size:11px;line-height:1.7;color:var(--app-muted)}.ft-granularity{display:flex;flex:none;padding:3px;gap:2px;border:1px solid var(--app-line);border-radius:10px;background:var(--app-raised)}.ft-granularity>button{min-width:30px;min-height:31px;border:0;border-radius:7px;background:transparent;color:var(--app-muted);font:inherit;font-size:11px;cursor:pointer}.ft-granularity [aria-pressed=true]{color:var(--app-accent);background:var(--app-soft);font-weight:600}.ft-legend{display:flex;align-items:center;gap:15px;margin:22px 0 13px;color:var(--app-muted);font-size:10px}.ft-legend>span{display:flex;align-items:center;gap:6px}.ft-legend i{width:7px;height:7px;border-radius:3px;background:#729fe7}.ft-legend span:nth-child(2)>i{background:#51b99c}.ft-legend small{margin-left:auto;font-size:9px}.ft-chart{display:flex;min-width:0;height:211px}.ft-axis{width:42px;flex:none}.ft-scroll{min-width:0;flex:1;overflow-x:auto;overscroll-behavior:contain;scrollbar-width:thin}.ft-scroll>svg{display:block;width:100%;height:211px;overflow:visible}.ft-chart text{fill:var(--app-muted);font:9px system-ui,sans-serif}.ft-grid{stroke:var(--app-line);stroke-width:1;stroke-dasharray:3 4}.ft-hit{fill:transparent}.ft-hit.selected{fill:var(--app-soft)}.ft-chart g{cursor:pointer}.ft-chart g:focus-visible{outline:1px solid var(--app-accent)}.ft-expense{fill:#729fe7}.ft-income{fill:#51b99c}.ft-values{display:flex;align-items:center;flex-wrap:wrap;gap:10px 15px;margin-top:19px;padding:13px 0 0;border-top:1px solid var(--app-line);font-size:10px;color:var(--app-muted);font-variant-numeric:tabular-nums}.ft-values>span{width:100%}.ft-values>b{font-size:11px;font-weight:500}.ft-expense-text{color:#729fe7}.ft-income-text{color:var(--app-income)}.ft-empty{display:flex;align-items:center;flex-direction:column;gap:12px;padding:40px 0;color:var(--app-muted)}.ft-empty>b{font-size:13px;color:var(--app-ink)}.ft-empty>p{margin:0;font-size:11px}.ft-granularity button:focus-visible,.ft-scroll:focus-visible{outline:2px solid var(--app-accent);outline-offset:2px}
</style>
